/* @lc app=leetcode id=2709 lang=kotlin */
class Solution { fun canTraverseAllPairs(nums: IntArray): Boolean = if (nums.size == 1) true else if (nums.any { it == 1 }) false else IntArray(100001) { it }.let { p -> DeepRecursiveFunction<Int, Int> { i -> if (p[i] == i) i else callRecursive(p[i]).also { p[i] = it } }.let { find -> nums.map { n -> (2..317).fold(n) { temp, d -> if (d * d <= temp && temp % d == 0) find.callRecursive(n).let { r1 -> find.callRecursive(d).let { r2 -> if (r1 != r2) p[r1] = r2 } }.run { generateSequence(temp) { if (it % d == 0) it / d else null }.last() } else temp }.let { final -> if (final > 1) find.callRecursive(n).let { r1 -> find.callRecursive(final).let { r2 -> if (r1 != r2) p[r1] = r2 } } } }.run { nums.map { find.callRecursive(it) }.distinct().size == 1 } } }